<script setup>
import {ref,watch,computed} from 'vue';
const props=defineProps({value:{default:null}});
const page=ref(0);watch(()=>props.value,()=>page.value=0);
const entries=computed(()=>Array.isArray(props.value)?props.value.slice(page.value*20,page.value*20+20):[]);
const labels={document_id:'Documento escriturado',document_ref:'Referência do documento',item:'Item',item_number:'Item',version:'Versão',file_id:'Arquivo original',sha256:'SHA-256',original:'Valor original',booked:'Valor escriturado',booked_cents:'Valor escriturado (centavos)',booked_total_cents:'Total escriturado (centavos)',base_xml:'Base no XML',base_recalculated:'Base recalculada',difference:'Diferença',components:'Componentes',ibs_xml:'IBS no XML',ibs_recalculated:'IBS recalculado',cbs_xml:'CBS no XML',cbs_recalculated:'CBS recalculada',ibs_rate:'Alíquota IBS',cbs_rate:'Alíquota CBS',ncm:'NCM',ex_code:'EX',actual_cst:'CST no XML',actual_cclass_trib:'cClassTrib no XML',expected_cst:'CST no catálogo',expected_cclass_trib:'cClassTrib no catálogo',strategy:'Critério de correspondência',parameter_source_row:'Linha da parametrização',catalog_version_id:'Versão do catálogo',source:'Fonte',source_row:'Linha de origem',description:'Descrição',cst:'CST',cclass_trib:'cClassTrib',issued_at:'Emissão',start:'Início',end:'Fim',scope:'Cobertura',quantity:'Quantidade',unit:'Unidade',unit_value:'Valor unitário',taxable_quantity:'Quantidade tributável',taxable_unit:'Unidade tributável',taxable_unit_value:'Valor unitário tributável',origin:'Origem da mercadoria',additional_information:'Informações adicionais',identifiers:'Identificadores',traceability:'Rastreabilidade',taxes:'Tributos informados',type:'Tipo',value:'Valor',confidence:'Confiança',reconciliation_identity:'Identidade para conciliação',key:'Chave',label:'Identificador',basis:'Critério',vProd:'Produtos',vServ:'Serviços',vFrete:'Frete',vSeg:'Seguro',vOutro:'Outras despesas',vII:'II',vDesc:'Desconto',vPIS:'PIS',vCOFINS:'Cofins',vICMS:'ICMS',vICMSUFDest:'ICMS UF destino',vFCP:'FCP',vFCPUFDest:'FCP UF destino',vICMSMono:'ICMS monofásico',vISSQN:'ISSQN',vIS:'Imposto Seletivo'};
Object.assign(labels,{"estimated_cost": "Custo estimado", "estimated_margin": "Margem estimada", "estimated_unit_cost": "Custo unitário estimado", "identity": "Identidade do produto", "basis": "Critério", "confidence": "Confiança", "key": "Chave", "label": "Identificador", "type": "Tipo", "input_quantity": "Quantidade de entradas", "output_quantity": "Quantidade de saídas", "input_value": "Valor de entradas", "output_value": "Valor de saídas", "layer": "Área da análise", "sample_limitation": "Limitado à amostra"});
Object.assign(labels,{name:'Nome / razão social',tax_id:'CNPJ / CPF',trade_name:'Nome fantasia',state_registration:'Inscrição estadual',municipal_registration:'Inscrição municipal',address:'Endereço',street:'Logradouro',number:'Número',complement:'Complemento',district:'Bairro',city:'Município',city_code:'Código do município',state:'UF',postal_code:'CEP',country:'País',phone:'Telefone',identification:'Identificação',protocol:'Protocolo',protocol_number:'Número do protocolo',status_code:'Código de situação',status_reason:'Motivo',received_at:'Recebido em',freight_mode:'Modalidade do frete',carrier:'Transportador',vehicle_plate:'Placa',vehicle_state:'UF do veículo',tax_authority:'Informação ao fisco',taxpayer:'Informação complementar',invoice_number:'Número da fatura',original_value:'Valor original',discount:'Desconto',net_value:'Valor líquido',references:'Documentos referenciados',vNF:'Valor da nota',vBC:'Base de ICMS',vBCST:'Base ICMS ST',vST:'ICMS ST',vIPI:'IPI',vTotTrib:'Tributos aproximados'});
const label=k=>labels[k]||k.replaceAll('_',' ');
const scalar=v=>v===null||v===undefined||v===''?'—':typeof v==='boolean'?(v?'Sim':'Não'):v;
</script>
<template><div class="audit-evidence"><template v-if="Array.isArray(value)"><p v-if="!value.length">Sem registros.</p><div v-if="value.length>20" class="actions"><button type="button" class="text-button" :disabled="!page" @click="page--">Anteriores</button><span>{{page*20+1}}–{{Math.min((page+1)*20,value.length)}} de {{value.length}}</span><button type="button" class="text-button" :disabled="(page+1)*20>=value.length" @click="page++">Próximos</button></div><details v-for="(entry,index) in entries" :key="page*20+index"><summary>Registro {{page*20+index+1}}</summary><AuditEvidence :value="entry"/></details></template><dl v-else-if="value&&typeof value==='object'"><div v-for="(entry,key) in value" :key="key"><dt>{{label(key)}}</dt><dd><AuditEvidence v-if="entry&&typeof entry==='object'" :value="entry"/><template v-else>{{scalar(entry)}}</template></dd></div></dl><span v-else>{{scalar(value)}}</span></div></template>
<style scoped>.audit-evidence{font-size:13px;overflow-wrap:anywhere}.audit-evidence dl{margin:8px 0}.audit-evidence dl>div{display:grid;grid-template-columns:minmax(130px,28%) minmax(0,1fr);gap:12px;padding:7px 0;border-bottom:1px solid #edf0f2}.audit-evidence dt{font-weight:600;color:#496477}.audit-evidence dd{margin:0;min-width:0}.audit-evidence details{padding:8px 0}.audit-evidence summary{cursor:pointer}@media(max-width:600px){.audit-evidence dl>div{grid-template-columns:1fr;gap:4px}}
</style>
